from itertools import permutations
def visits(path):
    x = y = 0
    for s in path:
        if s == 'R':
            x += 1
        else:
            y += 1
        if (x, y) == (2, 1):
            return True
    return False
ans = len([p for p in set(permutations('RRRRUUU')) if visits(p)])

