from itertools import permutations
def uses(path):
    x = y = 0
    for s in path:
        nx, ny = (x + 1, y) if s == 'R' else (x, y + 1)
        if (x, y) == (2, 1) and (nx, ny) == (3, 1):
            return True
        x, y = nx, ny
    return False
ans = len([p for p in set(permutations('RRRRUUU')) if not uses(p)])
